;\n  margin-bottom: 1rem;\n}\n.loading-container[_ngcontent-%COMP%]   p[_ngcontent-%COMP%], .error-container[_ngcontent-%COMP%]   p[_ngcontent-%COMP%] {\n  color: var(--color-text-medium);\n  margin: 0;\n}\n\n.error-container[_ngcontent-%COMP%]   .error-content[_ngcontent-%COMP%] {\n  max-width: 400px;\n}\n.error-container[_ngcontent-%COMP%]   .error-content[_ngcontent-%COMP%]   h2[_ngcontent-%COMP%] {\n  color: #E74C3C;\n  margin-bottom: 1rem;\n}\n.error-container[_ngcontent-%COMP%]   .error-content[_ngcontent-%COMP%]   p[_ngcontent-%COMP%] {\n  margin-bottom: 2rem;\n}\n\n@keyframes _ngcontent-%COMP%_spin {\n  0% {\n    transform: rotate(0deg);\n  }\n  100% {\n    transform: rotate(360deg);\n  }\n}\n@media (max-width: 768px) {\n  .confirmation-header[_ngcontent-%COMP%] {\n    padding: 2rem 0;\n  }\n  .confirmation-header[_ngcontent-%COMP%]   .success-icon[_ngcontent-%COMP%] {\n    font-size: 3rem;\n  }\n  .confirmation-main[_ngcontent-%COMP%] {\n    padding: 2rem 0;\n  }\n  .confirmation-layout[_ngcontent-%COMP%] {\n    grid-template-columns: 1fr;\n  }\n  .confirmation-sidebar[_ngcontent-%COMP%] {\n    order: -1;\n  }\n}\n.detail-section[_ngcontent-%COMP%], .card[_ngcontent-%COMP%] {\n  animation: _ngcontent-%COMP%_fadeInUp 0.6s ease-out;\n}\n\n@keyframes _ngcontent-%COMP%_fadeInUp {\n  from {\n    opacity: 0;\n    transform: translateY(20px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n.btn.btn-outline[_ngcontent-%COMP%] {\n  background: transparent;\n  border: 1px solid var(--color-border);\n  color: var(--color-text-dark);\n}\n.btn.btn-outline[_ngcontent-%COMP%]:hover {\n  background: var(--color-background);\n}\n.btn.btn-primary[_ngcontent-%COMP%] {\n  background: var(--color-primary);\n  color: white;\n  border: 1px solid var(--color-primary);\n}\n.btn.btn-primary[_ngcontent-%COMP%]:hover {\n  background: var(--color-primary-dark);\n}\n.btn.btn-secondary[_ngcontent-%COMP%] {\n  background: var(--color-text-medium);\n  color: white;\n 